const std = @import("std");
const testing = std.testing;

pub const SYNTHETIC_DATA_BADGE: []const u8 = "[SYNTHETIC_LAB_FIXTURE]";
pub const SYNTHETIC_PROVENANCE: []const u8 = "synthetic_lab_fixture";
pub const SYNTHETIC_ORIGIN_NOTICE: []const u8 =
    "This observation was generated by a controlled WireScope practice lab scenario. It is synthetic/loopback data and does not represent live public network traffic.";

pub const LabTargetError = error{
    PublicTargetForbiddenInLab,
    MalformedTarget,
    EmptyTarget,
};

/// Validates that a target is strictly confined to loopback or synthetic test domains.
/// Prevents lab exercises from ever contacting real public internet infrastructure.
pub fn validateLabTarget(target: []const u8) LabTargetError!void {
    if (target.len == 0) return LabTargetError.EmptyTarget;

    // Strip scheme if present (e.g. http://127.0.0.1:8080)
    var host = target;
    if (std.mem.indexOf(u8, host, "://")) |scheme_idx| {
        host = host[scheme_idx + 3 ..];
    }
    // Strip path if present
    if (std.mem.indexOfScalar(u8, host, '/')) |slash_idx| {
        host = host[0..slash_idx];
    }

    // Handle bracketed IPv6 like [::1]:80 or [::1]
    if (std.mem.startsWith(u8, host, "[")) {
        if (std.mem.indexOfScalar(u8, host, ']')) |end_bracket| {
            host = host[1..end_bracket];
        } else {
            return LabTargetError.MalformedTarget;
        }
    } else if (std.mem.indexOfScalar(u8, host, ':')) |colon_idx| {
        // Only treat as host:port if there is exactly one colon (IPv6 has 2+ colons)
        if (std.mem.indexOfScalar(u8, host[colon_idx + 1 ..], ':') == null) {
            host = host[0..colon_idx];
        }
    }

    if (host.len == 0) return LabTargetError.MalformedTarget;

    // 1. Loopback addresses and names
    if (std.mem.eql(u8, host, "127.0.0.1") or
        std.mem.eql(u8, host, "localhost") or
        std.mem.eql(u8, host, "::1"))
    {
        return;
    }

    if (std.mem.startsWith(u8, host, "127.")) {
        return;
    }

    // 2. Synthetic IETF reserved RFC 6761 / RFC 2606 test domains
    const allowed_suffixes = [_][]const u8{
        ".test",
        ".example",
        ".invalid",
        ".localhost",
        ".local",
    };

    for (allowed_suffixes) |suffix| {
        if (std.mem.endsWith(u8, host, suffix) or std.mem.eql(u8, host, suffix[1..])) {
            return;
        }
    }

    // Any other target is forbidden in lab scenarios
    return LabTargetError.PublicTargetForbiddenInLab;
}

/// Checks if a target string conforms to the lab's synthetic/loopback boundaries
pub fn isLabConfined(target: []const u8) bool {
    validateLabTarget(target) catch return false;
    return true;
}

test "synthetic: validates loopback and synthetic test domains" {
    try validateLabTarget("127.0.0.1");
    try validateLabTarget("127.0.0.1:8080");
    try validateLabTarget("http://127.0.0.1:8080/test");
    try validateLabTarget("localhost");
    try validateLabTarget("https://localhost:8443");
    try validateLabTarget("::1");
    try validateLabTarget("[::1]:8443");
    try validateLabTarget("127.10.20.30");
    try validateLabTarget("dns-failure.test");
    try validateLabTarget("http://api.local:8000");
    try validateLabTarget("mismatch.example");
}

test "synthetic: strictly rejects public internet targets in lab" {
    try testing.expectError(LabTargetError.PublicTargetForbiddenInLab, validateLabTarget("google.com"));
    try testing.expectError(LabTargetError.PublicTargetForbiddenInLab, validateLabTarget("8.8.8.8"));
    try testing.expectError(LabTargetError.PublicTargetForbiddenInLab, validateLabTarget("https://1.1.1.1:443"));
    try testing.expectError(LabTargetError.PublicTargetForbiddenInLab, validateLabTarget("api.github.com"));
    try testing.expectError(LabTargetError.PublicTargetForbiddenInLab, validateLabTarget("192.168.1.100"));
}

test "synthetic: markers and constants are defined" {
    try testing.expect(std.mem.indexOf(u8, SYNTHETIC_DATA_BADGE, "SYNTHETIC") != null);
    try testing.expect(std.mem.indexOf(u8, SYNTHETIC_ORIGIN_NOTICE, "practice lab") != null);
}
